-- MainStoryGuide: Night Elf saga journal (issue #14).
--
-- Hand-written prose, one page per chain quest and one epilogue per chain.
-- Close third person, world-focused; facts only from the Questie/PandaBase
-- facts in tools/sagas/nightelf.facts.json (tests/test_story_voice.py).

local _, ns = ...
ns.JournalEntries = ns.JournalEntries or {}
ns.JournalEpilogues = ns.JournalEpilogues or {}

local E = {
-- The Balance of Shadowglen ---------------------------------
[456] = { title = "The First Culling",
  body = "Conservator Ilthalaine asked for the balance of nature to be kept in Teldrassil. At his word, seven Young Nightsabers and four Young Thistle Boars were slain. The count was carried back to the conservator. The beasts of Teldrassil were fewer by that number." },
[97979] = { title = "What the Goddess Provides",
  body = "Shanda asked for two castings. Elune's Light was cast, and then Shadowmeld. Both were cast in Teldrassil, and the task ended with Shanda where it began. It asked for no hunt and no gathering. The two castings were the whole of the work." },
[458] = { title = "Seeking the Dryad",
  body = "Melithar Staghelm named a woodland protector in Teldrassil. The dryad known as Tarindrella was sought out, and she was found. Nothing more was asked than that meeting. The errand closed with Tarindrella, and her own work stood ready." },
[97977] = { title = "Totems of the Gnarlpine",
  body = "Tarindrella asked for Gnarlpine Totems. Four of them were gathered in Teldrassil, one totem at a time. The totems were carried back and placed before the dryad. The count of four was complete. The four totems now rested with Tarindrella." },
[457] = { title = "The Second Culling",
  body = "The balance of nature called for more. Conservator Ilthalaine named the Mangy Nightsabers and the Thistle Boars of Teldrassil. Seven of each were slain. The tally was brought back to the conservator. Twice now the beasts of Teldrassil had been thinned at his word." },
[459] = { title = "The Fel Moss",
  body = "Tarindrella's work as a woodland protector went on. She asked for Fel Moss, and eight were collected in Teldrassil. The moss was carried back to the dryad. Eight pieces of Fel Moss now rested with Tarindrella." },
[916] = { title = "Venom of the Webwood",
  body = "Gilshalan Windwalker of Aldrassil asked for Webwood Venom Sacs. Ten of them were gathered in Teldrassil. The sacs were carried back to Aldrassil and laid before Gilshalan Windwalker. The venom of the Webwood now rested in his keeping. Aldrassil stands in Shadowglen, and the work of the glen returns to it." },
[4495] = { title = "A Friend in the North",
  body = "Dirania Silvershine spoke of a good friend. Iverron was sought by the cave to the north. There, by the cave, he was found. The errand asked only for that finding, and what came next would begin with Iverron." },
[3519] = { title = "Word for Dirania",
  body = "Iverron was a friend in need. From the cave to the north, the road led back to Shadowglen. Dirania Silvershine was spoken with there. The road between the cave and the glen was walked again. Iverron's need now rested with Dirania Silvershine." },
[3521] = { title = "Gathering the Antidote",
  body = "Iverron's Antidote called for three things. Seven Hyacinth Mushrooms and four Moonpetal Lilies were gathered in Teldrassil. One Webwood Ichor was taken as well, the last of the three. All of it was brought to Dirania Silvershine in Shadowglen. The makings of the antidote now rested in her hands." },
[3522] = { title = "The Race to Iverron",
  body = "Dirania Silvershine handed over Iverron's Antidote. It was carried out of Shadowglen toward the cave to the north. There was a time limit, and the road was run against it. The antidote was placed in the hands of Iverron. The friend in need had been answered." },
[917] = { title = "The Webwood Egg",
  body = "Gilshalan Windwalker asked for more from the Webwood. A Webwood Egg was taken in Teldrassil. It was carried back to Aldrassil and placed before Gilshalan Windwalker. The venom sacs had come first, and now the egg joined them. Both now rested in his keeping at Aldrassil." },
[920] = { title = "Summons to the Heights",
  body = "Gilshalan Windwalker passed on Tenaron's Summons. The way led up Aldrassil in Shadowglen. Atop Aldrassil, at the height of the glen, Tenaron Stormgrip was found and spoken with. Nothing more was asked than that meeting. The work of the glen was done, and the summons opened a new road." },
-- Crown of the Earth ----------------------------------------
[921] = { title = "The Crystal Phial",
  body = "Tenaron Stormgrip waited atop Aldrassil. He gave over the Crystal Phial to be filled. The phial was filled in Teldrassil and carried back up Aldrassil. Tenaron Stormgrip received it again, filled as he had asked. So began the long road of the Crown of the Earth." },
[928] = { title = "The Road to Dolanaar",
  body = "From Aldrassil, the work moved on. Tenaron Stormgrip sent the Partially Filled Vessel onward through Teldrassil. It was carried to Dolanaar and placed in the hands of Corithras Moonrage. The vessel was not yet full, and more remained to be done. Its keeping now rested with Corithras Moonrage." },
[929] = { title = "The Jade Phial",
  body = "Corithras Moonrage gave over the Jade Phial. It was filled in Teldrassil. The phial was carried back to Dolanaar and returned to Corithras Moonrage. The Crystal Phial had come first, and now the jade followed it. The Crown of the Earth was taking shape one phial at a time." },
[933] = { title = "The Tourmaline Phial",
  body = "The work of Corithras Moonrage went on. The Tourmaline Phial was given out from Dolanaar to be filled. It was filled in Teldrassil and carried back along the road. Corithras Moonrage received it in Dolanaar. Crystal, jade and tourmaline had each been answered in turn." },
[7383] = { title = "The Amethyst Phial",
  body = "One more phial remained. Corithras Moonrage gave over the Amethyst Phial in Dolanaar. It was filled in Teldrassil and returned to him. With the amethyst, the series of phials came to its end. What had been gathered across Teldrassil now stood ready to go further." },
[935] = { title = "The Filled Vessel",
  body = "The vessel was full at last. Corithras Moonrage sent the Filled Vessel out of Dolanaar. It was carried across Teldrassil and into Darnassus. There it was placed in the hands of Arch Druid Fandral Staghelm. The work begun atop Aldrassil now stood before the arch druid." },
[98046] = { title = "The Drained Vessel",
  body = "The work went on in Darnassus. Arch Druid Fandral Staghelm passed on the Drained Vessel. It was carried to the Temple of the Moon. There it was delivered to Lariia, and its road went on. The Filled Vessel had come to the arch druid before it." },
[98065] = { title = "Before Tyrande Whisperwind",
  body = "Lariia gave over the Moonwell Remnants. They were carried within the Temple of the Moon in Darnassus. There they were brought before Tyrande Whisperwind. The road that began atop Aldrassil and ran through Dolanaar ended in the temple. The Crown of the Earth now rested with Tyrande Whisperwind." },
-- The Gnarlpine Corruption ----------------------------------
[475] = { title = "The Road to Starbreeze",
  body = "Athridas Bearmantle of Dolanaar sent the errand on across Teldrassil. At his word, the road was taken to Starbreeze Village. There Gaerolas Talvethren was sought out and found. No blade was drawn on this errand; a meeting was all that was asked. Dolanaar and Starbreeze Village were now joined by the same errand." },
[476] = { title = "Back to Dolanaar",
  body = "Gaerolas Talvethren of Starbreeze Village sent the errand back toward Dolanaar. The road was walked again across Teldrassil. In Dolanaar, Athridas Bearmantle was found once more. The errand returned to the hands that had begun it. The road between the two villages had now been walked both ways." },
[483] = { title = "Relics Brought Home",
  body = "Athridas Bearmantle asked for the Relics of Wakening. The relics were sought out in Teldrassil and retrieved. They were carried back to Dolanaar. There they were placed in the hands of Athridas Bearmantle. The Relics of Wakening now rest in his keeping." },
[486] = { title = "The End of Ursal",
  body = "Athridas Bearmantle of Dolanaar named one more foe: Ursal the Mauler. Ursal the Mauler was hunted down in Teldrassil and slain. Word of the kill was carried back to Dolanaar. Athridas Bearmantle received the report. With that, the last errand of Athridas Bearmantle in this chain was done." },
-- Denalan's Timberlings -------------------------------------
[997] = { title = "A Package of Earth",
  body = "Syral Bladeleaf had a package of Rare Earth bound for Lake Al'Ameth. The package was carried through Teldrassil to the lake. There it was placed in the hands of Denalan. A small delivery opened the way to larger work. The Rare Earth now rests with Denalan." },
[918] = { title = "Seeds of the Timberlings",
  body = "Denalan at Lake Al'Ameth asked for Timberling Seeds. Eight seeds were gathered in Teldrassil. They were carried back to the lake. Denalan received all eight. His work at Lake Al'Ameth had its first harvest." },
[919] = { title = "Sprouts for Denalan",
  body = "After the seeds, Denalan asked for more. Twelve Timberling Sprouts were sought next. The sprouts were gathered and brought back to Lake Al'Ameth. Denalan took them into his keeping. Seeds and sprouts both now lay in his hands." },
[922] = { title = "A Seed for Darnassus",
  body = "Denalan sent a single Timberling Seed beyond Lake Al'Ameth. The seed was carried from Teldrassil into Darnassus. There it was delivered to Rellian Greenspyre. One seed now linked the lake and the city. Rellian Greenspyre had the sample in hand." },
[923] = { title = "The Mossy Tumors",
  body = "Rellian Greenspyre in Darnassus asked for more than a seed. Five Mossy Tumors were sought out and gathered. Each was carried back to the city. Rellian Greenspyre received all five. The Mossy Tumors now lie in Darnassus with him." },
[2498] = { title = "Back to the Lake",
  body = "Rellian Greenspyre sent the errand back to Lake Al'Ameth. The road ran out of Darnassus and into Teldrassil. There Denalan was found and spoken with. Nothing more was asked than that meeting. The work of the city and the lake met again." },
[2499] = { title = "The Gargantuan Tumor",
  body = "Denalan at Lake Al'Ameth wanted the Gargantuan Tumor. That tumor was held by Oakenscowl. Oakenscowl was found, and the Gargantuan Tumor was taken. It was carried back to the lake and given to Denalan. The last piece of his work now rested in his hands." },
-- The Temple of the Moon ------------------------------------
[98391] = { title = "Word to the Sisterhood",
  body = "Laurna Morninglight in Teldrassil pointed the way to Darnassus. The road was taken into the city. There Sister Aquinne was sought out and spoken with. No task was set beyond that meeting. The errand had passed from Teldrassil into Darnassus." },
[2519] = { title = "Into the Temple",
  body = "Sister Aquinne sent the errand deeper into Darnassus. The way led to the Temple of the Moon. Inside, Priestess A'moora was found and spoken with. One meeting gave way to another. The Temple of the Moon now held the next step." },
[2518] = { title = "Lady Sathrah's Spinnerets",
  body = "Priestess A'moora asked for Lady Sathrah's Silvery Spinnerets. The spinnerets were taken and brought to the Temple of the Moon. There they were placed before the priestess. Priestess A'moora received them. The spinnerets were not yet at their final place." },
[2520] = { title = "Offering at the Fountain",
  body = "Priestess A'moora named the place for the spinnerets. Lady Sathrah's Silvery Spinnerets were set at the fountain inside the Temple of the Moon. The offering was left there in the temple. Word was brought back to Priestess A'moora. The spinnerets rest at the fountain." },
-- The Enchanted Glade ---------------------------------------
[937] = { title = "Belts of the Bloodfeather",
  body = "Sentinel Arynia Cloudsbreak stands in the Oracle Glade in Teldrassil. Her charge was a count of 6 Bloodfeather Belts. The belts were gathered one by one until the count was met. All 6 were brought back and laid before the sentinel in the Oracle Glade. The first of her charges was complete." },
[98392] = { title = "Three Amulets",
  body = "Sentinel Arynia Cloudsbreak had a second charge in the Oracle Glade. She called for three amulets: Hatescreech's Amulet, Windmistress Gaedress' Amulet and Witchmother Arysa's Amulet. Each was claimed and carried back through the glade. The three amulets were set before the sentinel." },
[98398] = { title = "Message in the Bark",
  body = "With the amulets gathered, Sentinel Arynia Cloudsbreak pointed to the Oracle Tree. The Oracle Tree Bark stood nearby in the Oracle Glade. It was found, and its message was received there. The Oracle Tree had a report to send onward." },
[940] = { title = "Report to Darnassus",
  body = "The Oracle Tree's report was meant for Darnassus. It left the Oracle Glade and was carried to the city. There it was delivered to Arch Druid Fandral Staghelm. The word of the tree now stood before the arch druid. What began among the belts and amulets of the glade reached Darnassus." },
-- Bashal'Aran -----------------------------------------------
[954] = { title = "The Blue Aura",
  body = "Thundris Windweaver spoke of a strange blue aura in Darkshore. The aura hung over the ruins of Bashal'Aran. The ruins were searched for its source. That search ended before Asterion. With Asterion, the work of Bashal'Aran began." },
[955] = { title = "Grell Earrings",
  body = "Asterion's first charge was a count of earrings. Eight Grell Earrings were asked for in Bashal'Aran. The earrings were gathered one by one until the count was met. All 8 were brought back to Asterion. The first task of the ruins was complete." },
[956] = { title = "The Moonstone Seal",
  body = "Asterion's next charge named a single object: the Ancient Moonstone Seal. The seal was obtained and carried back through Darkshore. It was set before Asterion in Bashal'Aran. The seal now rested within the ruins. Its fate was not yet settled." },
[957] = { title = "The Ancient Flame",
  body = "The Ancient Moonstone Seal was not meant to remain whole. Asterion sent it to the ancient flame in Ameth'Aran. There, at the flame, the seal was destroyed. Word of its end was carried back to Asterion in Bashal'Aran. The last charge of the ruins was fulfilled." },
-- Flight to Auberdine ---------------------------------------
[6344] = { title = "Sent to Nessa",
  body = "The errand began with Mydrannul in Darnassus. At Mydrannul's word, Nessa Shadowsong was sought out in Teldrassil. She was found and spoken with. Nothing more was asked than that meeting. One errand ended so that the next could begin." },
[6341] = { title = "Nessa's Collection",
  body = "Nessa Shadowsong had a collection ready to send. Nessa's Collection was taken from her hands in Teldrassil. It was carried to Vesprystus, the hippogryph master. Vesprystus received Nessa's Collection. The bounty of Teldrassil was ready for the sky." },
[6342] = { title = "Wings to Auberdine",
  body = "Vesprystus sent Nessa's Collection onward by air. A hippogryph carried it from Teldrassil to Auberdine in Darkshore. On landing, the collection was brought to Laird. Laird received it in Auberdine. Nessa's Collection had reached Darkshore." },
[6343] = { title = "Laird's Response",
  body = "Laird did not leave the matter unanswered. Laird's Response was set in hand in Auberdine. It was carried back from Darkshore to Teldrassil. There it was delivered to Nessa Shadowsong. The exchange that began with her collection now ended with Laird's Response." },
-- How Big a Threat? -----------------------------------------
[984] = { title = "The Corrupt Camp",
  body = "Terenthis of Auberdine asked how big a threat the furbolgs of Darkshore had become. A corrupt furbolg camp was sought out in Darkshore. The camp was found. Word of it was carried back to Terenthis in Auberdine. The first measure of the threat had been taken." },
[985] = { title = "Thinning the Blackwood",
  body = "Terenthis still asked how big a threat the corrupt furbolgs posed. Eight Blackwood Pathfinders were cut down in Darkshore. Five Windtalkers fell as well. The count was reported to Terenthis in Auberdine. The question of the furbolg threat now had a firmer answer." },
[4761] = { title = "To Thundris Windweaver",
  body = "Terenthis pointed the way to Thundris Windweaver in Auberdine. Thundris Windweaver was found in the town and spoken with. The matter of the furbolgs passed from one hand in Auberdine to the next." },
[4762] = { title = "Water from the Cliffspring",
  body = "Thundris Windweaver wanted the waters of the Cliffspring River examined. North of Auberdine, at the first waterfall along the river, a sample was drawn from the pool. The Cliffspring River Sample was carried back to Auberdine. Thundris Windweaver received it, and the river itself became part of the inquiry." },
[4763] = { title = "The Satyr Corruptor",
  body = "The Empty Cleansing Bowl was filled at the Auberdine Moonwell. Fruit, nut and grain were gathered from the northern Blackwood furbolg camps and mixed in the bowl. It was placed near the bonfire closest to the Cliffspring River, and the satyr corruptor was summoned. The Talisman of Corruption was taken and brought to Thundris Windweaver in Auberdine." },
[986] = { title = "Fine Moonstalker Pelts",
  body = "Terenthis of Auberdine turned to the matter of a lost master. Fine Moonstalker Pelts were sought across Darkshore. Five of them were found and gathered. The pelts were brought back to Terenthis in Auberdine." },
[993] = { title = "The Cloak for Volcor",
  body = "Terenthis sent the Enchanted Moonstalker Cloak out into Darkshore in search of Volcor. Volcor was found. The cloak was given into his hands. The lost master had been located, and the cloak had reached the one it was meant for." },
[995] = { title = "Out of the Cave",
  body = "Volcor was in a furbolg cave in Darkshore. The way out led through the cave itself. The escape was made through stealth, and the cave was left behind. The meeting with Terenthis took place in Auberdine. The search for the lost master came to its end there." },
-- The Master's Glaive ---------------------------------------
[947] = { title = "Stalks and a Death Cap",
  body = "Barithras Moonshade of Auberdine asked for mushrooms from the caves of Darkshore. Five Scaber Stalks were gathered. A single Death Cap was found as well. Both were brought back to Barithras Moonshade in Auberdine. The request was filled, and the count was complete." },
[948] = { title = "The Grove of the Ancients",
  body = "Barithras Moonshade pointed the way from Auberdine to the Grove of the Ancients in Darkshore. There Onu was found and spoken with. A new task in Darkshore began from that place." },
[944] = { title = "The Phial of Scrying",
  body = "Onu at the Grove of the Ancients asked for information. The information was gathered. The Phial of Scrying was then used to create a Scrying Bowl. Through the bowl, word passed to Onu at a distance." },
[949] = { title = "A Clue at the Glaive",
  body = "The Scrying Bowl pointed toward the Twilight's Hammer camp at the Master's Glaive. The camp was searched for a clue. The clue was found in the Twilight Tome. The tome lay in the camp at the Master's Glaive." },
[950] = { title = "The Insane Scribbles",
  body = "The Twilight Tome held the Insane Scribbles. They were recovered from the camp at the Master's Glaive. The scribbles were carried back to the Grove of the Ancients. Onu received them there. The clue from the Twilight's Hammer camp now rested with Onu." },
[951] = { title = "Six Relics for Onu",
  body = "Onu asked for the Mathystra Relics. Six of the relics were gathered in Darkshore. They were brought to the Grove of the Ancients. Onu received all six. The relics rest now with Onu at the grove." },
-- Expanding Horizons ----------------------------------------
[97914] = { title = "A Letter to Stormwind",
  body = "Thundris Windweaver of Auberdine in Darkshore sent a letter to Stormwind City. Thundris' Letter was carried out of Darkshore and on to Stormwind City. There it was placed in the hands of Baros Alexston. The letter from Auberdine had reached its mark." },
[97926] = { title = "The Reply from Stormwind",
  body = "Baros Alexston of Stormwind City answered the letter from Darkshore. Alexston's Reply was carried back out of Stormwind City. It was delivered to Thundris Windweaver in Auberdine. The exchange between Auberdine and Stormwind was complete, with a letter sent out and a reply returned to the hand that wrote the first." },
-- The Absent Minded Prospector ------------------------------
[729] = { title = "A Prospector Unaccounted For",
  body = "Archaeologist Hollee wanted word of Prospector Remtravel. The road led south through Darkshore. Prospector Remtravel was found and checked on, as Archaeologist Hollee had asked. The first step of the matter was settled there in Darkshore, and more work waited where the prospector stood." },
[731] = { title = "The Search for the Fossil",
  body = "Prospector Remtravel set out in Darkshore to search for a mysterious fossil. He was protected while the search went on. The mysterious fossil was found, and the guard over the prospector held. Word was carried back to Archaeologist Hollee in Auberdine. What had been only a search was now a find." },
[741] = { title = "A Fossil for Darnassus",
  body = "Archaeologist Hollee did not keep the mysterious fossil in Auberdine. It was sent on to Darnassus, into the care of Chief Archaeologist Greywhisker. The fossil crossed from Darkshore to the city and was placed in Chief Archaeologist Greywhisker's hands. The find had climbed to a higher authority, and its road was not yet over." },
[942] = { title = "The Road to Menethil",
  body = "Chief Archaeologist Greywhisker sent the mysterious fossil onward once more. Its next keeper was Archaeologist Flagongut in Menethil Harbor, in the Wetlands. The fossil left Darnassus and was carried to the harbor. It was delivered to Archaeologist Flagongut, far from the Darkshore ground where Prospector Remtravel had found it." },
-- Trek to Ashenvale -----------------------------------------
[990] = { title = "Into Ashenvale",
  body = "Sentinel Selarin of Darkshore pointed the way to Ashenvale. The trek led out of Darkshore and into the forest beyond. Raene Wolfrunner was found in Ashenvale, as Sentinel Selarin had directed. With that meeting, the road from Darkshore reached its end, and the work of Ashenvale began." },
[1008] = { title = "Twenty Wrathtail Heads",
  body = "Shindrell Swiftfire of Astranaar asked for 20 Wrathtail Heads. The heads were gathered until the full count was met. They were carried back to Astranaar and set before Shindrell Swiftfire. The tally of 20 was complete, and the request of Astranaar was answered." },
[991] = { title = "The Search for Teronis",
  body = "Raene Wolfrunner sought Teronis somewhere in Ashenvale. The search went out across the forest. Teronis was found, but only as a corpse. Teronis' Corpse marked the end of that search, and the matter of Raene's Cleansing was not yet finished." },
[1023] = { title = "Gem and Journal",
  body = "At Teronis' Corpse the next task began. The Glowing Gem was found. It was carried back to Astranaar with Teronis' Journal and given to Raene Wolfrunner. The journal and the gem now rested with Raene Wolfrunner." },
[1024] = { title = "The Moonwell to the Northeast",
  body = "Raene Wolfrunner sent the matter onward from Astranaar. The way led to a moonwell to the northeast. Shael'dryn was found there at the moonwell, as Raene Wolfrunner had directed. The trail that began with the search for Teronis now reached Shael'dryn." },
}
for id, e in pairs(E) do ns.JournalEntries[id] = e end

local P = {
shadowglen = { title = "Epilogue: The Balance of Shadowglen",
  body = "In Shadowglen in Teldrassil, the work was done one task at a time. Conservator Ilthalaine saw the nightsabers and thistle boars thinned twice over, and Tarindrella received Gnarlpine Totems and Fel Moss. Dirania Silvershine received Hyacinth Mushrooms, Moonpetal Lilies and Webwood Ichor, and Iverron's Antidote reached Iverron by the cave to the north. Gilshalan Windwalker took in venom sacs and a Webwood Egg at Aldrassil. At the last, the summons pointed to Tenaron Stormgrip atop Aldrassil." },
crown_of_the_earth = { title = "Epilogue: Crown of the Earth",
  body = "The Crown of the Earth began atop Aldrassil, where Tenaron Stormgrip received the Crystal Phial. The Partially Filled Vessel then went to Corithras Moonrage in Dolanaar. The Jade, Tourmaline and Amethyst Phials were filled and returned to him in turn. The Filled Vessel reached Arch Druid Fandral Staghelm in Darnassus, and the Drained Vessel passed to Lariia. The Moonwell Remnants came at last to Tyrande Whisperwind in the Temple of the Moon." },
gnarlpine = { title = "Epilogue: The Gnarlpine Corruption",
  body = "The chain began with a road from Athridas Bearmantle in Dolanaar to Gaerolas Talvethren in Starbreeze Village. Gaerolas Talvethren sent the errand back to Athridas Bearmantle. The Relics of Wakening were retrieved and brought to him in Dolanaar. Last of all, Ursal the Mauler was slain, and Athridas Bearmantle heard that the deed was done." },
timberlings = { title = "Epilogue: Denalan's Timberlings",
  body = "The chain began with a package of Rare Earth carried from Syral Bladeleaf to Denalan at Lake Al'Ameth. Timberling Seeds and Timberling Sprouts were gathered for his work. A seed went on to Rellian Greenspyre in Darnassus, who asked in turn for 5 Mossy Tumors. The road then led back to Denalan, and the Gargantuan Tumor was taken from Oakenscowl." },
temple_of_the_moon = { title = "Epilogue: The Temple of the Moon",
  body = "The chain began with Laurna Morninglight in Teldrassil and a road to Sister Aquinne in Darnassus. Sister Aquinne sent the errand on to Priestess A'moora in the Temple of the Moon. Lady Sathrah's Silvery Spinnerets were brought to the priestess. They were placed at the fountain inside the temple, and Priestess A'moora heard that it was done." },
enchanted_glade = { title = "Epilogue: The Enchanted Glade",
  body = "The Oracle Glade of Teldrassil was the ground where this chain began. Bloodfeather Belts and the amulets of Hatescreech, Windmistress Gaedress and Witchmother Arysa were laid before Sentinel Arynia Cloudsbreak. The Oracle Tree Bark gave its message. The report was carried to Arch Druid Fandral Staghelm in Darnassus." },
bashal_aran = { title = "Epilogue: Bashal'Aran",
  body = "Thundris Windweaver pointed to a strange blue aura in Darkshore. Its source was sought in the ruins of Bashal'Aran, where Asterion waited. Eight Grell Earrings and the Ancient Moonstone Seal were brought to Asterion. The seal was destroyed at the ancient flame in Ameth'Aran, and the work in Bashal'Aran was done." },
nessa = { title = "Epilogue: Flight to Auberdine",
  body = "Mydrannul of Darnassus pointed the way to Nessa Shadowsong. Nessa's Collection was handed to Vesprystus, the hippogryph master of Teldrassil. A hippogryph carried it across to Auberdine, where Laird received it. Laird's Response came back to Nessa Shadowsong, and the exchange between Teldrassil and Darkshore was complete." },
cliffspring = { title = "Epilogue: How Big a Threat?",
  body = "Terenthis of Auberdine sought the measure of the corrupt furbolgs of Darkshore. A camp was found, and Blackwood Pathfinders and Windtalkers fell. For Thundris Windweaver, a sample was drawn from the Cliffspring River and fruit, nut and grain were gathered from the northern Blackwood camps, and the Talisman of Corruption was taken after the satyr corruptor was summoned. Fine Moonstalker Pelts reached Terenthis, the Enchanted Moonstalker Cloak reached Volcor, and the escape from the furbolg cave ended with Terenthis in Auberdine." },
onu = { title = "Epilogue: The Master's Glaive",
  body = "Barithras Moonshade in Auberdine received Scaber Stalks and a Death Cap, then pointed the way to Onu at the Grove of the Ancients. Information was gathered, and the Phial of Scrying made a Scrying Bowl through which Onu spoke. The Twilight's Hammer camp at the Master's Glaive yielded a Twilight Tome, and the Insane Scribbles reached Onu. Six Mathystra Relics followed to the Grove of the Ancients." },
expanding_horizons = { title = "Epilogue: Expanding Horizons",
  body = "Thundris Windweaver in Auberdine sent a letter out of Darkshore. Thundris' Letter was carried to Baros Alexston in Stormwind City. Baros Alexston answered, and Alexston's Reply was carried back to Thundris Windweaver in Auberdine. The exchange between Auberdine and Stormwind was complete." },
prospector = { title = "Epilogue: The Absent Minded Prospector",
  body = "At Archaeologist Hollee's request, the road ran south through Darkshore to check on Prospector Remtravel. Prospector Remtravel was protected as he searched for the mysterious fossil, and word returned to Archaeologist Hollee in Auberdine. The fossil passed from Archaeologist Hollee to Chief Archaeologist Greywhisker in Darnassus. From Darnassus it was carried on to Archaeologist Flagongut in Menethil Harbor." },
ashenvale = { title = "Epilogue: Trek to Ashenvale",
  body = "From Darkshore, Sentinel Selarin directed the trek to Raene Wolfrunner in Ashenvale. In Astranaar, Shindrell Swiftfire received 20 Wrathtail Heads. Raene Wolfrunner's search for Teronis ended at Teronis' Corpse, and the Glowing Gem and Teronis' Journal were brought back to Raene Wolfrunner. The trail then turned to Shael'dryn at the moonwell to the northeast." },
}
for id, e in pairs(P) do ns.JournalEpilogues[id] = e end
